const char* RoleName(int r)
{
    switch(r)
    {
        case R_LEAD: return "ведущий"; case R_REAR: return "замыкающий"; case R_MARKSMAN: return "стрелок";
        case R_DRIVER: return "водитель"; case R_PILOT: return "пилот"; case R_MEDIC: return "медик";
    }
    return "боец";
}

